"""Generate TypeScript types from the FastAPI OpenAPI schema.

    .venv\\Scripts\\python -m api.generate_types

Output: ``web/src/api-types.ts``.
"""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path
from typing import Any

from config_loader import REPO_ROOT

HEADER = """// Generated by api/generate_types.py from the FastAPI OpenAPI schema.
// Do not edit by hand. Regenerate after changing api/schemas.py.
"""

IDENTIFIER = re.compile(r"^[A-Za-z_$][A-Za-z0-9_$]*$")


def _merge_all_of(schema: dict[str, Any]) -> dict[str, Any]:
    if "allOf" not in schema:
        return schema
    merged: dict[str, Any] = {"type": "object", "properties": {}, "required": []}
    for part in schema["allOf"]:
        part = _merge_all_of(part)
        merged["properties"].update(part.get("properties", {}))
        merged["required"].extend(part.get("required", []))
    for key, value in schema.items():
        if key != "allOf":
            merged[key] = value
    return merged


def ts_type(schema: dict[str, Any], indent: int = 0) -> str:
    schema = _merge_all_of(schema)
    if "$ref" in schema:
        return str(schema["$ref"]).rsplit("/", 1)[-1]
    if "const" in schema:
        return json.dumps(schema["const"])
    if "enum" in schema:
        return " | ".join(json.dumps(value) for value in schema["enum"])
    if "anyOf" in schema:
        parts = [ts_type(part, indent) for part in schema["anyOf"]]
        return " | ".join(dict.fromkeys(parts))
    if "oneOf" in schema:
        parts = [ts_type(part, indent) for part in schema["oneOf"]]
        return " | ".join(dict.fromkeys(parts))
    type_name = schema.get("type")
    if isinstance(type_name, list):
        parts = [ts_type({**schema, "type": item}, indent) for item in type_name]
        return " | ".join(dict.fromkeys(parts))
    if type_name == "array":
        item = ts_type(schema.get("items", {}), indent)
        if "|" in item and not item.startswith("("):
            item = f"({item})"
        return f"{item}[]"
    if type_name == "object" or "properties" in schema:
        properties: dict[str, Any] = schema.get("properties", {})
        required = set(schema.get("required", []))
        if not properties:
            extra = schema.get("additionalProperties")
            if isinstance(extra, dict):
                return f"Record<string, {ts_type(extra, indent)}>"
            return "Record<string, unknown>"
        pad = "  " * (indent + 1)
        lines = ["{"]
        for name, prop in properties.items():
            key = name if IDENTIFIER.match(name) else json.dumps(name)
            optional = "" if name in required else "?"
            lines.append(f"{pad}{key}{optional}: {ts_type(prop, indent + 1)};")
        lines.append("  " * indent + "}")
        return "\n".join(lines)
    if type_name in {"integer", "number"}:
        return "number"
    if type_name == "boolean":
        return "boolean"
    if type_name == "null":
        return "null"
    return "string"


def render_types(openapi: dict[str, Any]) -> str:
    schemas = (
        openapi.get("components", {}).get("schemas", {})
        if isinstance(openapi, dict)
        else {}
    )
    blocks: list[str] = [HEADER]
    for name in sorted(schemas):
        schema = _merge_all_of(schemas[name])
        if schema.get("enum") and schema.get("type") in {"string", "integer"}:
            blocks.append(f"export type {name} = {ts_type(schema)};\n")
        elif schema.get("type") == "object" or "properties" in schema:
            blocks.append(f"export interface {name} {ts_type(schema)}\n")
        else:
            blocks.append(f"export type {name} = {ts_type(schema)};\n")
    return "\n".join(blocks).rstrip() + "\n"


def generate(output: Path | None = None) -> Path:
    from api.app import app

    target = output or (REPO_ROOT / "web" / "src" / "api-types.ts")
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(render_types(app.openapi()), encoding="utf-8")
    return target


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--output",
        type=Path,
        default=REPO_ROOT / "web" / "src" / "api-types.ts",
    )
    args = parser.parse_args()
    path = generate(args.output)
    print(f"wrote {path}")


if __name__ == "__main__":
    main()
